package corpus.finallythrow

fun registerCleanup(callbacks: MutableList<() -> Unit>) {
    try {
        println("work")
    } finally {
        callbacks += { throw IllegalStateException("later") }
    }
}

package corpus.finallythrow

fun locallyHandled() {
    try {
        println("work")
    } finally {
        try {
            throw IllegalStateException("handled")
        } catch (caught: IllegalStateException) {
            println(caught.message)
        }
    }
}
